import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    L = int(input_data[0])
    C = int(input_data[1])

    idx = 2
    grid = []
    row_sums = []
    all_vars = set()

    for _ in range(L):
        row = input_data[idx:idx + C]
        idx += C
        s = int(input_data[idx])
        idx += 1
        grid.append(row)
        row_sums.append(s)
        for var in row:
            all_vars.add(var)

    col_sums = []
    for _ in range(C):
        col_sums.append(int(input_data[idx]))
        idx += 1

    equations = []
    # Equações das linhas
    for r in range(L):
        equations.append((grid[r], row_sums[r]))
    # Equações das colunas
    for c in range(C):
        col_vars = [grid[r][c] for r in range(L)]
        equations.append((col_vars, col_sums[c]))

    val = {}

    while len(val) < len(all_vars):
        found = False
        for eq_vars, total in equations:
            unknowns = set()
            known_sum = 0
            for v in eq_vars:
                if v in val:
                    known_sum += val[v]
                else:
                    unknowns.add(v)

            if len(unknowns) == 1:
                target_var = list(unknowns)[0]
                count = eq_vars.count(target_var)
                val[target_var] = (total - known_sum) // count
                found = True
                break
        if not found:
            break

    for v in sorted(all_vars):
        print(f"{v} {val[v]}")

if __name__ == '__main__':
    solve()
